// Fetches public GitHub repos at build time and writes src/app/data/repos.generated.ts.
// No runtime API calls: the site stays fully static. If the network fails, the
// existing generated file is kept so builds never break.
import { writeFile, access } from 'node:fs/promises';

const USER = 'connect-sethuvg';
const OUT = new URL('../src/app/data/repos.generated.ts', import.meta.url);
// Repos that are not portfolio projects (profile README, scratch, old portfolios, other sites).
const EXCLUDE = new Set([
  'connect-sethuvg',
  'connect-sethuvg.github.io',
  'example',
  'SethuMadhavanVG',
  'SethumadhavanVGPortfolio',
]);

const headers = { 'User-Agent': 'portfolio-build-script', Accept: 'application/vnd.github+json' };
if (process.env.GITHUB_TOKEN) headers.Authorization = `Bearer ${process.env.GITHUB_TOKEN}`;

async function gh(path, accept) {
  const res = await fetch(`https://api.github.com${path}`, {
    headers: accept ? { ...headers, Accept: accept } : headers,
  });
  if (!res.ok) throw new Error(`${res.status} ${path}`);
  return accept ? res.text() : res.json();
}

/** First meaningful prose paragraph of a README (skips headings, badges, html, code). */
function summarize(md) {
  // Untouched framework boilerplate READMEs say nothing about the project.
  if (!md || /generated (using|with) \[?Angular CLI/i.test(md)) return '';
  const cleaned = md.replace(/```[\s\S]*?```/g, '').replace(/<[^>]+>/g, '');
  for (const block of cleaned.split(/\n\s*\n/)) {
    const text = block
      .split('\n')
      .filter((l) => !/^\s*(#|!\[|\[!\[|[-*_]{3,}|\|)/.test(l))
      .map((l) => l.replace(/^\s*>\s?/, ''))
      .join(' ')
      .replace(/!\[[^\]]*\]\([^)]*\)/g, '')
      .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
      .replace(/[*_`]/g, '')
      .replace(/\s+/g, ' ')
      .trim();
    if (text.length > 30) {
      return text.length > 220 ? text.slice(0, 217).replace(/\s+\S*$/, '') + '…' : text;
    }
  }
  return '';
}

async function main() {
  const repos = (await gh(`/users/${USER}/repos?per_page=100&sort=pushed`)).filter(
    (r) => !r.fork && !r.archived && !EXCLUDE.has(r.name),
  );
  const out = [];
  for (const r of repos) {
    let readme = '';
    try {
      readme = summarize(await gh(`/repos/${USER}/${r.name}/readme`, 'application/vnd.github.raw'));
    } catch {
      /* no README */
    }
    out.push({
      name: r.name,
      description: r.description ?? '',
      readme,
      language: r.language ?? '',
      stars: r.stargazers_count,
      url: r.html_url,
      homepage: r.homepage || '',
      topics: r.topics ?? [],
      pushedAt: r.pushed_at,
    });
  }
  out.sort((a, b) => b.stars - a.stars || b.pushedAt.localeCompare(a.pushedAt));
  const ts =
    `// AUTO-GENERATED by scripts/fetch-repos.mjs — do not edit by hand.\n` +
    `import { GithubRepo } from './models';\n\n` +
    `export const GITHUB_REPOS: GithubRepo[] = ${JSON.stringify(out, null, 2)};\n`;
  await writeFile(OUT, ts);
  console.log(`[fetch-repos] wrote ${out.length} repos`);
}

main().catch(async (err) => {
  try {
    await access(OUT);
    console.warn(`[fetch-repos] ${err.message} — keeping existing repos.generated.ts`);
  } catch {
    await writeFile(
      OUT,
      `import { GithubRepo } from './models';\n\nexport const GITHUB_REPOS: GithubRepo[] = [];\n`,
    );
    console.warn(`[fetch-repos] ${err.message} — wrote empty repo list`);
  }
});
